CREATE OR REPLACE FUNCTION public.ajustar_parametros_frete(_nota uuid,_peso numeric,_cidade text,_uf text,_tabela uuid DEFAULT NULL,_motivo text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.can_finance(auth.uid()) OR length(trim(_motivo))<3 THEN RAISE EXCEPTION 'Informe justificativa e acesso autorizado';END IF; UPDATE notas_fiscais SET peso_frete=_peso,destino_entrega_cidade=nullif(trim(_cidade),''),destino_entrega_uf=nullif(upper(trim(_uf)),''),tabela_frete_id=_tabela WHERE id=_nota;INSERT INTO historico(entidade,entidade_id,acao,descricao,user_id) VALUES('nota',_nota,'ajuste_frete',_motivo,auth.uid());RETURN private.prepare_freight(_nota,_motivo);END $$;